// core/routes.ts
function labelOf(r) {
  return r.room ? `[\uBC29 ${r.room}] \u2192 ${r.session}` : `"${r.keywords}" \u2192 ${r.session}`;
}
function matches(r, keywords, room2) {
  return Boolean(keywords && r.keywords === keywords || room2 && r.room === room2);
}
function addRoute(routes, session, keywords, room2) {
  const rest = routes.filter((r) => !matches(r, keywords, room2));
  const entry = { session };
  if (keywords) entry.keywords = keywords;
  if (room2) entry.room = room2;
  return { routes: [...rest, entry], entry, replaced: rest.length !== routes.length };
}
function removeRoute(routes, keywords, room2) {
  const rest = routes.filter((r) => !matches(r, keywords, room2));
  return { routes: rest, removed: rest.length !== routes.length };
}
function renderRoutes(routes) {
  if (routes.length === 0) return null;
  return ["\uC9C8\uBB38 \uBC30\uBD84 (\uBC29 \uB4F1\uB85D\uC774 \uB0B1\uB9D0\uBCF4\uB2E4 \uBA3C\uC800):", ...routes.map((r) => `  ${labelOf(r)}`)].join(
    "\n"
  );
}
function mergeRoutes(current, imported) {
  const out = current.slice();
  for (const r of imported) {
    if (out.some((x) => r.keywords && x.keywords === r.keywords || r.room && x.room === r.room))
      continue;
    const entry = { session: r.session };
    if (r.keywords) entry.keywords = r.keywords;
    if (r.room) entry.room = r.room;
    out.push(entry);
  }
  return out;
}

// core/rooms.ts
function classifyRooms(rooms2, held, heldByOther) {
  const mine = new Set(held);
  const other = new Set(heldByOther);
  return Object.entries(rooms2).map(([room2, label]) => ({
    room: room2,
    label,
    mark: mine.has(room2) ? "mine" : other.has(room2) ? "other" : "empty"
  }));
}
var ICON = { mine: "\u{1F7E2}", other: "\u{1F535}", empty: "\u26AA" };
var NOTE = {
  mine: "\uC774 \uC138\uC158\uC774 \uBC1B\uB294 \uC911",
  other: "\uB2E4\uB978 \uC138\uC158\uC774 \uB2F4\uB2F9 \uC911",
  empty: "\uBE44\uC5B4 \uC788\uC74C \u2014 \uC9C0\uAE08 \uC544\uBB34\uB3C4 \uBC1B\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4"
};
function renderRooms(list) {
  return list.map((r) => `  ${ICON[r.mark]} ${r.room} (${r.label})   ${NOTE[r.mark]}`).join("\n");
}
function choiceLabel(r) {
  const tail = r.mark === "other" ? " \xB7 \uACE0\uB974\uBA74 \uADF8 \uC138\uC158\uC740 \uC218\uC2E0\uC744 \uC783\uC2B5\uB2C8\uB2E4" : "";
  return `${ICON[r.mark]} ${r.room} (${r.label}) \u2014 ${NOTE[r.mark]}${tail}`;
}

