var context = null;
if (host.isTeam && nodeOk) {
  installStatusline();
  context = await link.boot(Number(process.env.MESHWORK_CONTEXT_WAIT_MS ?? 1500)).catch((e) => {
    log(`\uCF24 \uB54C \uC5F0\uACB0 \uC2E4\uD328: ${e.message}`);
    return null;
  });
}
var cfg0 = loadConfig(P.config) ?? {};
var instructions = buildInstructions({
  team: host.isTeam,
  context,
  roomName: (id2) => cfg0.rooms?.[id2]?.name ?? id2,
  ...host.isTeam && !nodeOk ? {
    notReady: `Node ${MIN_NODE} \uC774\uC0C1\uC774 \uD544\uC694\uD569\uB2C8\uB2E4(\uC9C0\uAE08 ${host.runtime}) \u2014 \uC124\uCE58\uD55C \uB4A4 \uC0C8 \uC138\uC158\uC744 \uC5EC\uC138\uC694`
  } : host.isTeam && !context ? { notReady: notReadyText(link.state, { lang: "ko" }) } : {}
});
var mcp = new Server(
  { name: "meshwork", version: PLUGIN_VERSION },
  {
    capabilities: {
      // 이 키가 채널 등록의 전부. claude/channel/permission 은 일부러 선언하지 않는다 — 선언하면 팀원이 이 세션의
      // 도구 실행을 원격으로 승인할 수 있게 된다(보안 경계 — 더하지 말 것 · 연결 계약 §3)
      experimental: { "claude/channel": {} },
      tools: {}
    },
    instructions
  }
);
holder.mcp = mcp;
mcp.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: TOOLS }));
mcp.setRequestHandler(CallToolRequestSchema, async (req) => {
  const raw = req.params.arguments ?? {};
  const args = Object.fromEntries(
    Object.entries(raw).map(([k, v]) => [k, v === void 0 || v === null ? void 0 : String(v)])
  );
  return callTool(plugin, req.params.name, args);
});
var transport = new StdioServerTransport();
var shutdown = () => {
  link.close();
  process.exit(0);
};
transport.onclose = shutdown;
process.stdin.on("end", shutdown);
process.stdin.on("close", shutdown);
await mcp.connect(transport);
plugin.mcpConnected();
if (host.isTeam) {
  plugin.startHeartbeat();
  const nudge = setTimeout(
    () => {
      const st = link.state;
      if (!nodeOk) {
        void plugin.notify(
          `[Meshwork] Node ${MIN_NODE} \uC774\uC0C1\uC774 \uD544\uC694\uD569\uB2C8\uB2E4(\uC9C0\uAE08 ${host.runtime}) \u2014 https://nodejs.org \uC5D0\uC11C \uC124\uCE58\uD55C \uB4A4 \uC0C8 \uC138\uC158\uC744 \uC5EC\uC138\uC694.`,
          { kind: "system" }
        ).catch(() => void 0);
      } else if (st.kind === "no_server" || st.kind === "logged_out" || st.kind === "no_org") {
        void plugin.notify(`[Meshwork] ${notReadyText(st, { lang: plugin.lang })}`, { kind: "system" }).catch(() => void 0);
      } else if (st.kind === "open" && link.session && !link.session.held.length && plugin.dir.rooms.length > 1) {
        void plugin.notify(
          `[\uBC1B\uB294 \uBC29 \uC5C6\uC74C] \uC774 \uC138\uC158\uC740 \uBC1B\uB294 \uBC29\uC774 \uC5C6\uC5B4 \uD300 \uBA54\uC2DC\uC9C0\uB97C \uBC1B\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4 \u2014 /meshwork:room \uC73C\uB85C \uBC1B\uC744 \uBC29\uC744 \uACE0\uB974\uC138\uC694.`,
          { kind: "system" }
        ).catch(() => void 0);
      }
    },
    Number(process.env.MESHWORK_NUDGE_DELAY_MS ?? 4e3)
  );
  nudge.unref?.();
}
